-- External audit fixes 2026-10-13 - VERIFY (SELECT only)
-- generated by scripts/audit/apply-audit-fixes.ts. Non-production target only (worpsqwqgnspddnrtnvq). One DO block = one transaction: any failure rolls everything back.
-- problems: 8 new problem versions, sets: 5 new set versions (draft -> validate -> publish; previous version archived; access tier inherited).
-- Run (coordinator): npx supabase db query --linked -f <this file>

select p.id as problem_id, pv.version_no, pv.status, pv.quality->'auditFix'->>'patch' as patch, (pv.render_check->>'ok') as render_ok
  from problems p join problem_versions pv on pv.id = p.published_version_id where p.id in ('54cbdf03-1c8d-49ad-ac29-8b3b8d776e18', '23cbc7d6-ebc7-443b-ad7c-78171a826ef3', '0e1652f7-e9f3-4da6-a2b1-fd6ef992dade', '1dc7acc0-2662-4442-9d65-ff8068763c9c', 'd5e5fa81-fb0a-4d7e-bf39-676309864b47', 'd743987b-e981-4ba9-be06-d5860aefbbb7', '29942b62-3469-4d26-aed1-d2a3310391b1', 'ce78a0fc-01c7-402d-9711-ad8ea6d7b1d2') order by patch;
select s.name, s.version_no, s.status, s.access_tier, s.readiness_status,
       (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
       (select count(*) from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = s.id and p.published_version_id is distinct from i.problem_version_id) as stale_items
  from mock_exam_sets s where s.set_group_id in ('ecb17501-26e8-4e01-9b5e-8cc0a10a2799', '0952b774-6156-4d09-a5fa-fb4943b20dac', 'c21312d0-2b9a-4ee5-8196-e98aa5f2fc17', 'a57a7d5e-850c-43f2-991d-785450e72018', 'f99e778c-3b8f-4e4a-8116-c5bc29a338a9') and s.status in ('published', 'draft') order by s.name;
